"any_repository_has_fulltext": false}, "primary_location": {"id": "doi:10.1007/s10994-026-07060-8", "doi": "https://doi.org/10.1007/s10994-026-07060-8", "is_oa": true, "landing_page_url": "https://doi.org/10.1007/s10994-026-07060-8", "pdf_url": "https://link.springer.com/content/pdf/10.1007/s10994-026-07060-8.pdf", "source": {"id": "https://openalex.org/S62148650", "display_name": "Machine Learning", "issn_l": "0885-6125", "issn": ["0885-6125", "1573-0565"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["anvur-scientific", "ccf-b", "cwts-core", "dongbi-b", "jufo-3", "norway-2", "poland-140", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310319900", "host_organization_name": "Springer Science+Business Media", "host_organization_lineage": ["https://openalex.org/P4310319900", "https://openalex.org/P4310319965"], "host_organization_lineage_names": ["Springer Science+Business Media", "Springer Nature"], "type": "journal"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Machine Learning", "raw_type": "journal-article"}, "abstract": "Abstract Large Language Models (LLM) have demonstrated remarkable capabilities across various applications, but their deployment raises critical safety concerns as potential misuse poses significant societal risks. This survey reviews the end-to-end security and safety pipeline of LLMs, focusing on the interaction between users and model responses. We categorize the system into five key components: attacks, defenses, safety alignment, metrics and guarding mechanisms. Attacks involve crafting adversarial inputs to exploit model vulnerabilities. Defenses act as countermeasures, aiming to detect and prevent such inputs before processing. Safety alignment ensures that, even when attacks reach the model, its responses remain consistent with ethical and policy-aligned behavior. Guarding mechanisms operate post-response to flag, filter, or block unsafe outputs. Each of these stages is subject to rigorous evaluation metrics to assess their effectiveness, robustness, and limitations. As LLMs evolve toward more general-purpose intelligence, these safety considerations become increasingly critical for the development of robust and trustworthy AI systems. Finally, we highlight open challenges and future research directions to advance the security and alignment of LLMs."}]", "excerpt_truncated": true, "source_sha256": "5d26c02d60d13b46edd4c09ffe6fe46a3ffb86dbab1a2ccb944a9ccc8bdc7e14", "verification_required": true, "topic_domain": "assumption_challenge", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1007/s10994-026-07060-8", "doi:10.1007/s10994-026-07060-8.pdf", "openalex:W7219230570"], "source_candidates": ["https://doi.org/10.1007/s10994-026-07060-8", "https://link.springer.com/content/pdf/10.1007/s10994-026-07060-8.pdf"], "source_candidate_identities": {}}
